func testAccCloudIdentityPolicy_cloudidentityPolicyBasicExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
provider "google" {
  scopes = [
    "https://www.googleapis.com/auth/cloud-identity.policies",
    "https://www.googleapis.com/auth/cloud-platform",
    "https://www.googleapis.com/auth/userinfo.email",
  ]
}

resource "google_cloud_identity_policy" "primary" {
  customer = "customers/%{cust_id}"

  policy_query {
    org_unit = "orgUnits/%{org_unit_id}"
  }

  setting {
    type = "settings/detector.word_list"
    value_json = jsonencode({
      displayName = "Project Sensitive Terms"
      description = "Detector for project-specific confidential keywords."
      wordList = {
        words = ["confidential", "top-secret"]
      }
    })
  }
}
`, context)
}

